statement:
The integer `n` is even. Start from the array `perm` of length `n` with `perm[i] = i` for every index `i` (0-indexed). One operation shuffles it like a perfect riffle: build a fresh array `arr` of length `n` where

- for every even `i`, `arr[i] = perm[i / 2]`;
- for every odd `i`, `arr[i] = perm[n / 2 + (i - 1) / 2]`;

and then `arr` becomes the new `perm`. Return the smallest number of operations, at least 1, after which `perm` equals `[0, 1, ..., n - 1]` again.

validator:
function validate([n]) {
  if (!Number.isInteger(n) || n < 2 || n > 1000) return 'n is an integer from 2 to 1000.';
  if (n % 2 !== 0) return 'n must be even.';
  return null;
}

reference:
function reinitializePermutation(n) {
  let perm = Array.from({ length: n }, (_, i) => i);
  let operations = 0;

  while (true) {
    const arr = new Array(n);
    for (let i = 0; i < n; i++) {
      if (i % 2 === 0) {
        arr[i] = perm[i / 2];
      } else {
        arr[i] = perm[n / 2 + (i - 1) / 2];
      }
    }
    perm = arr;
    operations++;
    if (perm.every((value, index) => value === index)) {
      return operations;
    }
  }
}

brute:
function reinitializePermutation(n) {
  // Position j moves to 2j mod (n - 1) (ends fixed), so the answer is the order of 2 modulo n - 1.
  if (n === 2) return 1;
  let k = 1;
  let power = 2 % (n - 1);
  while (power !== 1) {
    power = (power * 2) % (n - 1);
    k++;
  }
  return k;
}

